// Threshold rules -- centralized here, versioned via methodology_version
// (1). Numeric truth comes entirely from compute_video_benchmarks()'s
// SQL-computed median/percentile/sample_size/confidence_label; this
// Code node only applies fixed thresholds to decide which rule_ids
// fire -- see docs/architecture/analytics-strategy-pipeline.md#deterministic-observations.
const THRESHOLDS = {
  ctr_below_median_all_time: { group: 'all_time', metric: 'ctr', ratio: 0.85, direction: 'below', insight_type: 'thumbnail_style' },
  ctr_above_median_all_time: { group: 'all_time', metric: 'ctr', ratio: 1.15, direction: 'above', insight_type: 'thumbnail_style' },
  views_below_median_recent_5: { group: 'recent_5', metric: 'views', ratio: 0.70, direction: 'below', insight_type: 'topic_selection' },
  watch_time_above_median_all_time: { group: 'all_time', metric: 'watch_time_minutes', ratio: 1.15, direction: 'above', insight_type: 'video_duration' },
  avg_percentage_viewed_below_median_all_time: { group: 'all_time', metric: 'average_percentage_viewed', ratio: 0.85, direction: 'below', insight_type: 'first_30_second_pacing' },
};
const b = $input.first().json;
const benchmarks = b.benchmarks || [];
const observations = [];
for (const [ruleId, rule] of Object.entries(THRESHOLDS)) {
  const row = benchmarks.find((x) => x.benchmark_group === rule.group && x.metric_name === rule.metric);
  if (!row || row.sample_size < 3 || row.benchmark_metric_value === null || row.video_metric_value === null) continue;
  const fired = rule.direction === 'below' ? row.video_metric_value < row.benchmark_metric_value * rule.ratio : row.video_metric_value > row.benchmark_metric_value * rule.ratio;
  if (!fired) continue;
  const pctDiff = row.benchmark_metric_value !== 0 ? Number((((row.video_metric_value - row.benchmark_metric_value) / row.benchmark_metric_value) * 100).toFixed(2)) : null;
  observations.push({
    rule_id: ruleId, metric_name: rule.metric, benchmark_group: rule.group, video_metric_value: row.video_metric_value,
    benchmark_metric_value: row.benchmark_metric_value, percentage_difference: pctDiff, direction: rule.direction,
    sample_size: row.sample_size, confidence_label: row.confidence_label, video_benchmark_id: row.id,
    statement: rule.metric + ' is ' + (pctDiff !== null ? Math.abs(pctDiff) + '% ' : '') + rule.direction + ' the ' + rule.group + ' median at this checkpoint.',
    _insight_type: rule.insight_type,
  });
}
return [{ json: { channel_id: b.channel_id, published_video_id: b.published_video_id, checkpoint: b.checkpoint, observations } }];

const prompt = $json.data;
const ctx = $('Prepare Get-Prompt Input').first().json._ctx;
const model = (prompt.model_compatibility && prompt.model_compatibility[0]) || 'claude-opus-4-8';
const schema = { type: 'object', additionalProperties: false, required: ['insights'], properties: { insights: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['insight_type', 'insight_kind', 'recommendation', 'sample_size', 'evidence_rule_ids', 'confidence_label'], properties: { insight_type: { type: 'string', enum: ['topic_selection','hook_structure','first_30_second_pacing','video_duration','section_pacing','cta_placement','thumbnail_style','title_style','publishing_schedule','visual_treatment','chapter_structure','traffic_targeting'] }, insight_kind: { type: 'string', enum: ['observation','recommendation'] }, subject: { type: ['string','null'] }, observation: { type: ['string','null'] }, recommendation: { type: 'string' }, sample_size: { type: 'integer', minimum: 0 }, confidence_label: { type: 'string', enum: ['exploratory','low','moderate','high'] }, evidence_rule_ids: { type: 'array', items: { type: 'string' }, minItems: 1 }, limitations: { type: ['string','null'] } } } } } };
const userPayload = { published_video_id: ctx.published_video_id, checkpoint: ctx.checkpoint, observations: ctx.observations };
return [{ json: { ctx, model, requestBody: { model, max_tokens: 4096, system: prompt.content, messages: [{ role: 'user', content: JSON.stringify(userPayload) }], output_config: { format: { type: 'json_schema', schema } } } } }];

const resp = $input.first().json;
const prep = $('Prepare Anthropic Request').first().json;
const textBlock = (resp.content || []).find((b) => b.type === 'text');
let result = null; let parse_failed = true;
if (textBlock) { try { result = JSON.parse(textBlock.text); parse_failed = !result || !Array.isArray(result.insights); } catch (e) { parse_failed = true; } }
return [{ json: { parse_failed, ctx: prep.ctx, model: prep.model, insights: result ? result.insights : [], usage: resp.usage || {}, provider_request_id: resp.id || null } }];

// Claude Opus pricing -- same $/M-token constants used at every other
// LLM call site in this repo (Step 6/7's generate-shot-list.json etc).
const j = $('Parse LLM Response').first().json;
const inputTokens = j.usage.input_tokens || 0;
const outputTokens = j.usage.output_tokens || 0;
const totalCost = Math.round(((inputTokens / 1000000) * 5 + (outputTokens / 1000000) * 25) * 1000000) / 1000000;
return [{ json: { channel_id: j.ctx.channel_id, content_project_id: null, workflow_run_id: null, workflow_step_id: null, provider: 'anthropic', service_type: 'llm', model: j.model, quantity: inputTokens + outputTokens, unit: 'token', unit_price_usd: null, total_cost_usd: totalCost, provider_request_id: j.provider_request_id, estimated: false, metadata: { published_video_id: j.ctx.published_video_id, checkpoint: j.ctx.checkpoint } } }];
